    jdbc.update("UPDATE incident_tasks SET status = 'DONE', done_by = ?, done_at = ?,"
                    + " updated_at = ?, version = version + 1 WHERE id = ?",
            actor, Timestamp.from(at), Timestamp.from(at), id);
}

